from lib import *
S = SS('w67')
steps = [
    step("迭代解析 example.com 的 A 记录:自己从根服务器开始,每一问 RD = 0(不要求对方替我递归)。第 1 问问根服务器 a.root-servers.net:转介到 com.,授权区 13 个 NS,附加区带 6 个 IPv4 胶水地址,耗时 242.6 ms;第 2 问问 com. 的一个服务器 l.gtld-servers.net:转介到 example.com.,授权区 2 个 NS,附加区带 6 个胶水地址,251.6 ms;第 3 问问 hera.ns.cloudflare.com:回答 1 条 A(AA),287.5 ms。一共 3 问、总耗时 783 ms,拿到 172.66.147.243 和 104.20.23.154。每一问只回答“我知道的最近一层”:根不知道 example.com 但知道谁管 com.;com. 的服务器不知道地址但知道谁管 example.com;最后才是权威回答。", t=tl(S(1)), mark=lidx(S(1), '第 1 问', '第 2 问'), done=lidx(S(1), '第 3 问', '共 3 问', '每一问只回答'), b=bars([['第 1 问 根', 242.6, '242.6 ms'], ['第 2 问 com.', 251.6, '251.6 ms'], ['第 3 问 权威', 287.5, '287.5 ms']], 290, mark=[], done=[0, 1, 2]), kv=KV([['第 1 问(根)', '转介到 com.'], ['第 2 问(com.)', '转介到 example.com.'], ['第 3 问(权威)', '回答 A,AA'], ['总计', '3 问 783 ms']], ['总计'])),
    step("转介报文的样子(再问一次根服务器):RCODE = NOERROR,标志 QR TC(没有 AA——根对 example.com 不权威,也没有 RA——根不做递归),回答区是空的;授权区 13 条 NS(com. 的 13 个服务器 l.gtld-servers.net、j.gtld-servers.net、h.gtld-servers.net …),附加区 11 条胶水(A 6 条、AAAA 5 条),整个报文 489 字节。TC 位置位了:没有用 EDNS0 时 UDP 响应的上限是 512 字节,附加区放不下全部胶水,于是被截断。胶水记录的作用是让你不必为了找到 NS 的地址而再回头去解析 NS 的名字。", t=tl(S(2)), mark=lidx(S(2), 'RCODE NOERROR', '附加区(胶水记录)'), done=lidx(S(2), '授权区(前 3 条)', '标志里没有 AA'), kv=KV([['RCODE', 'NOERROR'], ['标志', 'QR TC(无 AA、无 RA)'], ['授权 / 附加', '13 条 NS / 11 条胶水'], ['大小', '489 字节(被截断)']], ['标志'])),
    step("几个名字各要几问(从根开始迭代):example.com 3 问 757 ms;iana.org 3 问 708 ms(根 → org. → 权威);www.github.com 3 问 668 ms,最后一问同时回答了 1 条 A 和 1 条 CNAME(权威服务器顺手把 CNAME 指向的地址也带上了,省了一问);python.org 3 问 620 ms,最后回答 4 条 A。每一问 178~303 ms,基本就是到各服务器的往返时间,三问加起来 620~757 ms。异常的是 www.bbc.co.uk:只用 1 问、7.6 ms,根服务器 a 就“回答”了一个 A 记录(199.59.148.206)——根服务器不可能直接回答这个名字,到 a 根的正常往返也要 220 ms 以上。下面第六节专门查这件事。", t=tl(S(3)), mark=lidx(S(3), 'www.bbc.co.uk', '汇总'), done=lidx(S(3), 'example.com:', 'iana.org:', 'www.github.com:', 'python.org:'), b=bars([['example.com', 757, '757 ms / 3 问'], ['iana.org', 708, '708 ms / 3 问'], ['www.github.com', 668, '668 ms / 3 问'], ['python.org', 620, '620 ms / 3 问'], ['www.bbc.co.uk(异常)', 8, '8 ms / 1 问']], 757, mark=[4], done=[0, 1, 2, 3]), kv=KV([['正常名字', '3 问,约 620~757 ms'], ['www.github.com', '最后一问同时带回 CNAME 和 A'], ['www.bbc.co.uk', '1 问 8 ms(异常)']], ['www.bbc.co.uk'])),
    step("同样的名字交给递归解析器 1.1.1.1:本机只发 1 个查询(RD = 1),其余 1.1.1.1 替我们做。各问 5 次:example.com 的往返 [286, 284, 235, 294, 284] ms,中位 284 ms;www.github.com [286, 292, 301, 306, 230] ms,中位 292 ms——这两个都落在“到 1.1.1.1 的网络往返”(约 230~300 ms)上,缓存命中的话 1.1.1.1 马上回答,所以这个数字基本只是网络往返。对照自己迭代:example.com 757 ms、www.github.com 668 ms。www.bbc.co.uk 却是 [36, 42, 38, 48, 44] ms,中位 42 ms,比到 1.1.1.1 的往返快得多,同样异常。", t=tl(S(4)), mark=lidx(S(4), 'www.bbc.co.uk:5 次往返', '对比自己迭代'), done=lidx(S(4), 'example.com:5 次往返', 'www.github.com:5 次往返'), b=bars([['递归 1.1.1.1 example.com', 284, '284 ms'], ['自己迭代 example.com', 757, '757 ms'], ['递归 1.1.1.1 www.github.com', 292, '292 ms'], ['自己迭代 www.github.com', 668, '668 ms']], 757, mark=[], done=[0, 1, 2, 3]), kv=KV([['递归 1 个查询', '约 284~292 ms(基本是网络往返)'], ['自己迭代 3 问', '668~757 ms'], ['www.bbc.co.uk', '42 ms(异常)']], ['递归 1 个查询'])),
    step("根服务器有 13 个名字(a ~ m.root-servers.net),都是任播:同一个名字背后有很多台机器,你连上的是网络上离你最近的那一台。用 EDNS0 取回全部 13 个的地址后,对每个问一次 example.com 的转介(各 3 次取中位):a 252、b 227、c 171、d 240、e 280、f 7、g 248、h 111、i 122、j 7、l 8、m 126 ms,k 没有响应。最快的 j 是 7 ms,最慢的 e 是 280 ms,相差近 40 倍——f、j、l 三个根的往返只有 7~8 ms,说明它们有离本机很近的节点。同一个“a 根”在第一节里的往返是 242 ms,但 j 根只要 7 ms,任播让“离得近的根”近得多。", t=tl(S(5)), mark=lidx(S(5), 'a 252'), done=lidx(S(5), '根服务器名字共'), b=bars([['j 根', 7, '7 ms'], ['f 根', 7, '7 ms'], ['l 根', 8, '8 ms'], ['h 根', 111, '111 ms'], ['i 根', 122, '122 ms'], ['m 根', 126, '126 ms'], ['c 根', 171, '171 ms'], ['b 根', 227, '227 ms'], ['d 根', 240, '240 ms'], ['g 根', 248, '248 ms'], ['a 根', 252, '252 ms'], ['e 根', 280, '280 ms']], 280, mark=[0, 11], done=[]), kv=KV([['根服务器名字', '13 个(a~m)'], ['有响应', '12 个(k 没有)'], ['最快 / 最慢', 'j 7 ms / e 280 ms']], ['最快 / 最慢'])),
    step("www.bbc.co.uk 的异常。向一个根本没有 DNS 服务的地址 192.0.2.1(文档专用地址)发 example.com、www.bbc.co.uk、www.facebook.com 三个查询,3 秒内各 0 个响应——所以这条路径上并不是“任何发往 53 端口的包都被应答”。但向根服务器 198.41.0.4 问 www.bbc.co.uk,3 秒内收到 2 个响应,都在 +6 ms,都“来自 198.41.0.4”:一个答案是 157.240.11.40(TTL 122),另一个是 199.59.148.209(TTL 75),标志都是 QR RD RA。这不可能是根服务器:根不做递归(不会有 RA),不会直接回答 www.bbc.co.uk 的地址,同一个查询也不会给出两个互相矛盾的答案,而且 6 ms 比到该根的正常往返(约 220~300 ms)快得多。我的结论是:在这台机器所在网络的路径上,有设备对部分域名的查询抢先伪造了应答(第三节里的 8 ms 回答也是同一件事)。这个结论只限于这个网络环境,而且我没有查是谁、为什么。它对后面的 DNSSEC、DoT / DoH 两篇很重要:明文 UDP 的 DNS 无法分辨真假。", t=tl(S(6)), mark=lidx(S(6), '向 198.41.0.4 问 www.bbc.co.uk', '向 192.0.2.1 问 www.facebook.com'), done=lidx(S(6), '向 192.0.2.1 问 example.com', '向 192.0.2.1 问 www.bbc.co.uk'), b=bars([['伪造响应到达', 6, '+6 ms'], ['到 a 根的正常往返', 242.6, '242.6 ms']], 250, mark=[0], done=[1]), kv=KV([['向无服务的 192.0.2.1 问', '0 个响应'], ['向 a 根问 www.bbc.co.uk', '2 个互相矛盾的响应,+6 ms,带 RA'], ['结论', '路径上有设备伪造应答(仅限本网络)']], ['结论'])),
]
